import{_ as u,a0 as n,w as s,s as a,I as e,x as t,a1 as l,A as p,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Drupal、IoT 和開源硬件之間的交集 | LCTT x X-CMD","titleTemplate":false,"description":"Drupal、IoT 和開源硬件之間的交集 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Drupal、IoT 和開源硬件之間的交集 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Drupal、IoT 和開源硬件之間的交集 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160502 The intersection of Drupal, IoT, and open hardware","title":"Drupal、IoT 和開源硬件之間的交集","tag":"201608","desc":""},"relativePath":"201608/20160502 The intersection of Drupal, IoT, and open hardware.md","filePath":"[post].md"}'),d={name:"201608/20160502 The intersection of Drupal, IoT, and open hardware.md"};function D(T,r,m,f,b,g){const o=n("Link");return s(),a("div",null,[r[24]||(r[24]=e("h1",{id:"drupal、iot-和開源硬件之間的交集",tabindex:"-1"},[t("Drupal、IoT 和開源硬件之間的交集 "),e("a",{class:"header-anchor",href:"#drupal、iot-和開源硬件之間的交集","aria-label":"Permalink to “Drupal、IoT 和開源硬件之間的交集”"},"​")],-1)),r[25]||(r[25]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/drupal_blue_gray_lead.jpeg?itok=t7W_KD-D",alt:""})],-1)),e("p",null,[r[2]||(r[2]=t("來認識一下 ",-1)),l(o,{href:"https://www.drupal.org/u/amber-himes-matz"},{default:p(()=>[...r[0]||(r[0]=[t("Amber Matz",-1)])]),_:1}),r[3]||(r[3]=t("，她是來自 Lullabot Education 旗下的 ",-1)),l(o,{href:"https://events.drupal.org/neworleans2016/"},{default:p(()=>[...r[1]||(r[1]=[t("Drupalize.Me",-1)])]),_:1}),r[4]||(r[4]=t(" 的產品經理以及培訓師。當她沒有倒騰 Arduino、Raspberry Pi 以及電子穿戴設備時，通常會在波特蘭 Drupal 用户組裏擔任辯論主持人。",-1))]),e("p",null,[r[6]||(r[6]=t("在即將舉行的 ",-1)),l(o,{href:"https://events.drupal.org/neworleans2016/"},{default:p(()=>[...r[5]||(r[5]=[t("DrupalCon NOLA",-1)])]),_:1}),r[7]||(r[7]=t(" 大會上，Amber 將主持一個關於 Drupal 和 IoT 的主題。如果你會去參加，也想了解下開源硬件，IoT 和 Drupal 之間的交集，那這個將很合適。如果你去不了新奧爾良的現場也沒關係，Amber 還分享了許多很酷的事情。在這次採訪中，她講述了自己參與 Drupal 的原因，一些她自己喜歡的開源硬件項目，以及 IoT 和 Drupal 的未來。",-1))]),r[26]||(r[26]=e("p",null,[e("img",{src:"https://opensource.com/sites/default/files/images/life/Interview%20banner%20Q%26A.png",alt:""})],-1)),r[27]||(r[27]=e("p",null,[e("strong",null,"你是怎麼加入 Drupal 社區的？")],-1)),r[28]||(r[28]=e("p",null,"在這之前，我在一家大型非盈利性機構市場部的“網站管理部”工作，飛快地批量生產出各種定製 PHP/MySQL 表單。最終我厭煩了這一切，並開始在網上尋找更好的方式。然後我找到了 Drupal 6 並開始沉迷進去。過了幾年，在一次跳槽之後，我發現了波特蘭 Drupal 用户組，然後在裏面找了一份全職的 Drupal 開發者工作。我一直經常參加在波特蘭的聚會，在那裏我找到了大量的社區、朋友和專業方面的發展。一個偶然的機會，我在 Lullabot 找了一份培訓師的工作，為 Drupalize.Me 提供內容。現在，我管理着 Drupalize.Me 的內容輸出，負責編撰 Drupal 8 相關的內容，還很大程度地參與到波特蘭 Drupal 社區中。我是今年的協調員，尋找並安排演講者們。",-1)),r[29]||(r[29]=e("p",null,[e("strong",null,"我們想知道：什麼是 Arduino 原型，你是怎麼找到它的，以及你用 Arduino 做過的最酷的事是什麼？")],-1)),e("p",null,[r[9]||(r[9]=t("Arduino，Raspberry Pi，以及可穿戴電子設備，這些年到處都能聽到這些術語。我在幾年前通過 Becky Stern 的 YouTube 秀（最近由 Becky 繼續主持，每週三播出）發現了 ",-1)),l(o,{href:"https://www.adafruit.com/beckystern"},{default:p(()=>[...r[8]||(r[8]=[t("Adafruit 的可穿戴電子設備",-1)])]),_:1}),r[10]||(r[10]=t("。我被那些可穿戴設備迷住了，還訂了一套 LED 縫製工具，不過沒做出任何東西。我不太適合它。我沒有任何電子相關的背景，而且在我被那些項目吸引的時候，我根本不知道怎麼做出那樣的東西，它似乎看上去太遙遠了。",-1))]),r[30]||(r[30]=i('<p>後來，我在 Coursera 上找到了一個“物聯網”專題。（很時髦，對吧？）我很快就喜歡上了。我最終找到了 Arduino 是什麼的解釋，以及所有這些其他的重要術語和概念。我訂了一套推薦的 Arduino 初學者套件，還附帶了一本如何上手的小冊子。當我第一次讓 LED 閃爍的時候，開心極了。我在聖誕節以及之後有兩個星期的假期，然而我什麼都沒幹，就一直根據初學者小冊子給 Arduino 電路編程。很奇怪我覺得很放鬆！我太喜歡了。</p><p>在一月份的時候，我開始構思我自己的原型設備。在知道我需要主持公司培訓的開場白時，我用五個 LED 燈和 Arduino 搭建了一個開場白視覺計時器的原型。</p><p><img src="https://opensource.com/sites/default/files/resize/amber-arduino-lightning-talk-timer-400x400.jpg" alt=""></p><p>這是一次巨大的成功。我還做了我的第一個可穿戴項目，一件會發光的連帽衫，使用了和 Arduino IDE 兼容的 Gemma 微控制器，一個小的圓形可縫製部件，然後用可導電的線縫起來，將一個滑動可變電阻和衣服帽口的收縮繩連在一起，用來控制縫到帽子裏的五個 NeoPixel 燈的顏色。這就是我對原型設計的看法：做一些很好玩也可能會有點實際用途的瘋狂項目。</p><p><strong>Drupal 和 IoT 帶來的最大機遇是什麼？?</strong></p><p>IoT 與 Web Service 以及 Drupal 分層趨勢實際並沒有太大差別。就是將數據從一個東西傳送到另一個東西，然後將數據轉換成一些有用的東西。但數據是如何送達？能用來做點什麼？你覺得現在就有一大堆現成的解決方案、應用、中間層，以及 API 嗎？採用 IoT，這隻會繼續成幾何指數級的增長。我覺得，給我任何一個設備或“東西”，總有辦法來將它連接到互聯網上，有很多辦法。而且有大量現成的代碼庫來幫助創客們將他們的數據從一個東西傳到另一個東西。</p><p>那麼 Drupal 在這裏處於什麼位置？首先，Web services 將是第一個明顯的地方。但作為一個創客，我不希望將時間花在編寫 Drupal 的訂製模組上。我想要的是即插即用！所以我很高興出現這樣的模組能連接 IoT 雲端 API 和服務，比如 ThingSpeak，Adafruit.io，IFTTT，以及其他的。我覺得也有一個很好的商業機會，在 Drupal 裏構建一套 IoT 雲服務，允許用户發送和存儲他們的傳感器數據，並可以製成表格和圖像，還可以寫一些插件可以響應特定數據或闕值。每一個 IoT 雲 API 服務都是一個細分的機會，所以能留下很大空間給其他人。</p><p><strong>這次 DrupalCon 你有哪些期待？</strong></p><p>我喜歡與 Drupal 上的朋友重逢，認識一些新的人，還能見到 Lullabot 和 Drupalize.Me 的同事（我們是分佈式的公司）！Drupal 8 有太多東西可以去探索了，我們給我們的客户們提供了海量的培訓資料。所以，我很期待參與一些 Drupal 8 相關的主題，以及跟上最新的開發進度。最後，我對新奧爾良也很感興趣！我曾經在 2004 年去過，很期待將這次將看到哪些改變。</p><p><strong>談一談你這次 DrupalCon 上的演講：“超越閃爍：將 Drupal 加到你的 IoT 遊樂場中”。別人為什麼要參加？他們最重要的收穫會是什麼？</strong></p><p>我的主題的標題是，“超越閃爍：將 Drupal 加到你的 IoT 遊樂場中”，假設我們所有人都處在同一進度和層次，你不需要了解任何關於 Arduino、物聯網、甚至是 Drupal，都能跟上。我將從用 Arduino 讓 LED 燈閃爍開始，然後我會談一下我自己在這裏面的最大收穫：玩、學、教和做。我會列出一些曾經激勵過我的例子，它們也很有希望能激發和鼓勵其他聽眾去嘗試一下。然後，就是展示時間！</p><p>首先，第一個東西。它是一個建築提醒信號燈。在這個展示裏，我會説明如何將信號燈連到互聯網上，以及如何響應從雲 API 服務收到的數據。然後，第二個東西。它是一個蒸汽朋克風格 iPhone 外殼形式的“天氣手錶”。有一個小型 LED 矩陣用來顯示我的天氣的圖標，一個氣壓和温度傳感器，一個 GPS 模組，以及一個 Bluetooth LE 模組，都連接到一個 Adafruit Flora 微控制器上。第二個東西能通過藍牙連接到我的 iPhone 上的一個應用，並將天氣和位置數據通過 MQTT 協議發到 Adafruit.io 的服務器！然後，在 Drupal 這邊，我會從雲端下載這些數據，更新天氣信息，然後更新地圖。所以大家也能體驗一下通過web service、地圖和 Drupal 8 的功能塊所能做的事情。</p><p>學習和製作這些展示原型是一次燒腦的探險，我也希望有人能參與這個主題並感染一點我對這種技術交叉的傳染性熱情！我很興奮能分享一些我的發現。</p><hr>',14)),e("p",null,[r[12]||(r[12]=t("via: ",-1)),l(o,{href:"https://opensource.com/business/16/5/drupalcon-interview-amber-matz"},{default:p(()=>[...r[11]||(r[11]=[t("https://opensource.com/business/16/5/drupalcon-interview-amber-matz",-1)])]),_:1})]),e("p",null,[r[16]||(r[16]=t("作者：",-1)),l(o,{href:"https://opensource.com/users/jhibbets"},{default:p(()=>[...r[13]||(r[13]=[t("Jason Hibbets",-1)])]),_:1}),r[17]||(r[17]=t(" 譯者：",-1)),l(o,{href:"https://github.com/zpl1025"},{default:p(()=>[...r[14]||(r[14]=[t("zpl1025",-1)])]),_:1}),r[18]||(r[18]=t(" 校對：",-1)),l(o,{href:"https://github.com/wxy"},{default:p(()=>[...r[15]||(r[15]=[t("wxy",-1)])]),_:1})]),e("p",null,[r[21]||(r[21]=t("本文由 ",-1)),l(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...r[19]||(r[19]=[t("LCTT",-1)])]),_:1}),r[22]||(r[22]=t(" 原創翻譯，",-1)),l(o,{href:"https://linux.cn/"},{default:p(()=>[...r[20]||(r[20]=[t("Linux中國",-1)])]),_:1}),r[23]||(r[23]=t(" 榮譽推出",-1))])])}const w=u(d,[["render",D]]);export{L as __pageData,w as default};
